public int equalMinOnly(int[] arr) {
    int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
    for (int a : arr) { min = Math.min(min, a); max = Math.max(max, a); }
    int D = max - min;
    int[] dp = new int[D + 1];
    int[] coins = {1, 2, 5};
    for (int v = 1; v <= D; v++) {
        dp[v] = Integer.MAX_VALUE;
        for (int c : coins) {
            if (v - c >= 0 && dp[v - c] != Integer.MAX_VALUE) {
                dp[v] = Math.min(dp[v], dp[v - c] + 1);
            }
        }
    }
    int total = 0;
    for (int a : arr) total += dp[a - min];
    return total; // can overcount: target is wrongly pinned to min
}

