    int min = Integer.MAX_VALUE;
    for (int a : arr) min = Math.min(min, a);
    int best = Integer.MAX_VALUE;
    for (int base = min; base >= min - 2; base--) {
        int total = 0;
        for (int a : arr) total += coins(a - base);
        best = Math.min(best, total);
    }
    return best;
}

private int coins(int d) {
    return d / 5 + (d % 5) / 2 + (d % 5) % 2;
}

